/bin/bash -lc "Rscript - <<'RS'
for (f in list.files('/workspace/tmp', full.names=TRUE)) {
 cat('FILE', f, '\\n')
 x <- readRDS(f)
 cat('class:', paste(class(x), collapse=','), '\\n')
 cat('typeof:', typeof(x), 'length:', length(x), '\\n')
 if (isS4(x)) cat('S4 slots:', paste(slotNames(x), collapse=', '), '\\n')
 if (is.data.frame(x) || is.matrix(x)) {
   cat('dim:', paste(dim(x), collapse=' x '), '\\n')
   cat('colnames:', paste(colnames(x), collapse=', '), '\\n')
   cat('rownames head:', paste(head(rownames(x)), collapse=', '), '\\n')
   print(head(x, 2))
 }
 if (is.list(x) && "'!is.data.frame(x)) {
   cat('"'names:', paste(names(x), collapse=', '), '\\n')
   for(n in names(x)) cat(n, 'class', paste(class(x[[n]]), collapse=','), 'dim', paste(dim(x[[n]]), collapse='x'), '\\n')
 }
}
RS"

